import{_ as t,c as n,j as e,a as l,o as r}from"./chunks/framework.CqbvlPrP.js";const u=JSON.parse('{"title":"第二百零二章 拳头打利刀","description":"","frontmatter":{},"headers":[],"relativePath":"meditation/巴利文大藏经/202第二百零二章 拳头打利刀.md","filePath":"meditation/巴利文大藏经/202第二百零二章 拳头打利刀.md"}'),o={name:"meditation/巴利文大藏经/202第二百零二章 拳头打利刀.md"};function _(s,a,i,d,p,c){return r(),n("div",null,a[0]||(a[0]=[e("h1",{id:"第二百零二章-拳头打利刀",tabindex:"-1"},[l("第二百零二章 拳头打利刀 "),e("a",{class:"header-anchor",href:"#第二百零二章-拳头打利刀","aria-label":'Permalink to "第二百零二章 拳头打利刀"'},"​")],-1),e("p",null,"完全读懂巴利文大藏经",-1),e("p",null,"相应部20相应5经/矛经(譬喻相应/因缘篇/如来记说)",-1),e("p",null,"有个时候，佛陀住在舍卫城的祇树林给孤独园，有一天，佛陀对出家弟子们说：“弟子们，如果有一把锋利的刀，有一个男子，他心里想：「我要用拳头打到这把刀的刀刃上，要将这把锋利的刀打断。」弟子们，你们现在是怎么想的，这个男子他能够用自己的拳头将锋利的刀打断吗？”",-1),e("p",null,"出家弟子们回答：“世尊，这个男子他是不可能将这把锋利的刀打断的，他将自己的拳头打在锋利的刀刃上，他的拳头将会被这把刀切成两半，他将会由此疼痛哀嚎、满地打滚。”",-1),e("p",null,"佛陀说：“弟子们，同样的道理，那些不修习善法、解脱法的人，他们也将被欲望折磨的痛苦不堪、痛不欲生。弟子们，他们将会被烦恼和痛苦吞噬、困扰。",-1),e("p",null,"那些经常修习善法、解脱法的人，他们将会从欲望中解脱出来，他们将会从烦恼和痛苦中解脱出来，因此，弟子们，你们应该这样去修行：「我们要多修习善法、解脱法，我们要熄灭内心的欲望，我们不要用拳头去碰那些锋利如刀的欲望，这样我们就不会被欲望的利刀伤害，这样我们就不会被烦恼和痛苦吞噬、困扰。我们要努力精进的修行善法、解脱法，我们要养成修行善法、解脱法的习惯，要让我们修习善法、解脱法的行为如同吃饭喝水一样的平常。」弟子们，你们就应该这样去修行。",-1),e("p",null,"佛陀说法后，听法的出家弟子们都再次的顶礼佛陀，随喜赞叹佛陀说法的无量功德，他们都按着佛陀所说的法去修行。",-1)]))}const f=t(o,[["render",_]]);export{u as __pageData,f as default};
